<?php require 'config/database.php';$page_title='Create Order';$suppliers=$pdo->query('SELECT * FROM suppliers ORDER BY supplier_name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$pdo->beginTransaction();$pdo->prepare('INSERT INTO orders(supplier_id,order_date,expected_delivery_date,notes,status) VALUES(?,?,?,?,?)')->execute([$_POST['supplier_id'],$_POST['order_date'],$_POST['expected_delivery_date'],$_POST['notes'],$_POST['status']]);$orderId=$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit,unit_price) VALUES(?,?,?,?,?,?)');$product=$pdo->prepare('INSERT INTO products(product_name,default_unit,supplier_id) VALUES(?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)');foreach($_POST['product_name'] as $i=>$name){if(trim($name)===''||floatval($_POST['quantity'][$i])<=0)continue;$product->execute([trim($name),$_POST['unit'][$i],$_POST['supplier_id']]);$item->execute([$orderId,$pdo->lastInsertId(),trim($name),$_POST['quantity'][$i],$_POST['unit'][$i],$_POST['unit_price'][$i]]);}$pdo->commit();redirect('order_view.php?id='.$orderId);}catch(Exception $e){$pdo->rollBack();$error='Could not save order.';}}
require 'includes/header.php'; ?>
<div class="panel"><h2>Order Information</h2><?php if(!$suppliers):?><p class="notice">Please add a supplier before creating an order.</p><?php else:?><form method="post"><div class="form-grid"><div><label>Supplier *</label><select required name="supplier_id"><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['supplier_name'])?></option><?php endforeach;?></select></div><div><label>Status</label><select name="status"><option>Pending</option><option>Scheduled</option></select></div><div><label>Order Date *</label><input required type="date" name="order_date" value="<?=date('Y-m-d')?>"></div><div><label>Expected Delivery Date *</label><input required type="date" name="expected_delivery_date"></div><div class="full"><label>Notes</label><textarea name="notes"></textarea></div></div><h3>Order Items</h3><div id="items"><div class="item-row"><div><label>Product *</label><input required name="product_name[]"></div><div><label>Quantity *</label><input class="qty" required min="0.01" step="0.01" oninput="calculateTotal()" type="number" name="quantity[]"></div><div><label>Unit *</label><input required name="unit[]" value="pcs"></div><div><label>Unit Price</label><input class="price" min="0" step="0.01" oninput="calculateTotal()" type="number" name="unit_price[]" value="0"></div><div><label>Subtotal</label><input class="subtotal" readonly value="0.00"></div><button type="button" class="btn danger" onclick="removeItem(this)">×</button></div></div><button type="button" class="btn light" onclick="addItem()">+ Add Item</button><div class="total">Order Total: ₱<span id="order-total">0.00</span></div><div class="form-actions"><button class="btn">Save Order</button><a class="btn secondary" href="orders.php">Cancel</a></div></form><?php endif;?></div><?php require 'includes/footer.php'; ?>
